const ExpressionSourceSchema = z
  .strictObject({
    kind: z.literal('expression').meta(field('Evaluate JSONata locally.')),
    jsonata: ExpressionSchema.meta(
      field('JSONata source; return a declared route id for decisions.'),
    ),
