  private async failRun(
    runId: string,
    authoredFailure: RunFailure | InternalRunFailureError,
    records: readonly EventDraft[] = [],
  ): Promise<void> {
    const run = await this.ports.runs.get(runId);
    if (!run || isTerminal(run.status)) return;
