await scenario('LOG', async () => {
  const hits = t.logger.lines.filter((l) => /QA486-(LIT|IN|PATH)/.test(JSON.stringify(l.obj) + l.msg));
  const authoredLogs = t.logger.lines.filter((l) => JSON.stringify(l.obj).includes('"boundary"'));
