await scenario('B01u', async () => {
  const loop = await publishOk('B01u', chain('b01u', [{ id: 's', kind: 'script', label: 's', config: { command: join(WORK, 'no-such-dir', 'missing-qa486.exe'), args: [], stdin: 'none' } }]));
