});

// --------- CH-DEDUP-B: transient unexpected mapping fault (SCRIPTED-CLOCK) then successful Resume ---------
await scenario('CH-DEDUP-B', async () => {
  const loop = await publishOk('CH-DEDUP-B', chain('dedupb', [sub(childOk)]));
  if (!loop) return;
