});
await scenario('B16', () => authoredInf('B16', chain('b16', [inf({ prompt: { template: `Hi ${inc('B16')}` } })]), { code: 'TEMPLATE_ERROR', boundary: 'inference.prompt.template', cause: TEMPLATE_RENDER, message: (c) => `Inference prompt template failed. ${c}` }));

